function symbols({body}) {
 if(!Array.isArray(body))throw Error('Binance did not return the symbol list');
 const list=body.map(x=>x?.symbol);if(list.some(x=>typeof x!=='string'||!x||x.length>64)||new Set(list).size!==list.length)throw Error('Invalid or duplicate Binance symbols');
 return {symbols:list};
}

const a=symbols({body:$input.first().json}).symbols;const out=[];for(let i=0;i<a.length;i+=20){const expected=a.slice(i,i+20);out.push({json:{expected,url:'https://data-api.binance.vision/api/v3/ticker/24hr?symbols='+encodeURIComponent(JSON.stringify(expected))}})}return out;

function check({body,expected}) {
 if(!Array.isArray(body)||!Array.isArray(expected))throw Error('Invalid ticker batch');
 const seen=new Set(),allowed=new Set(expected),matches=[];for(const item of body){if(!item||typeof item.symbol!=='string'||!allowed.has(item.symbol)||seen.has(item.symbol))throw Error('Ticker batch has an unexpected or duplicate symbol');seen.add(item.symbol);const percent=parseFloat(item.priceChangePercent);if(typeof item.priceChangePercent!=='string'||!Number.isFinite(percent)||typeof item.lastPrice!=='string')throw Error('Invalid ticker fields');if(Math.abs(percent)>=15)matches.push({symbol:item.symbol,percent,price:item.lastPrice})}if(seen.size!==expected.length)throw Error('Ticker batch is incomplete');return {matches};
}

return [{json:check({body:$input.first().json,expected:$('Read batches one at a time').first().json.expected})}];

function format({matches}) {
 const entries=[...matches].sort((a,b)=>b.percent-a.percent),messages=[];let current='';for(const x of entries){const line='```'+x.symbol+' Price changed by '+x.percent+'% \n Last Price: '+x.price+'```\n';if(line.length>1000)throw Error('Ticker message exceeds 1000 characters');if(current.length+line.length>1000){messages.push(current);current=''}current+=line}if(current)messages.push(current);return {messages};
}

return format({matches:$input.all().flatMap(x=>x.json.matches)}).messages.map(text=>({json:{text}}));
